const curry = (fn, ...args) => {
  if (args.length >= fn.length) {
    return fn.apply(null, args)
  } else {
    const newFn = (...extraArgs) => curry(fn, ...args, ...extraArgs)
    Object.defineProperty(newFn, 'length', { value: fn.length - args.length })
    return newFn
  }
}

