function toTree (data) {
  data = data || []
  const map = {}
  const roots = []
  data.map(x => map[x.id] = x)
  data.map(x => {
    if (map[x.parent]) {
      map[x.parent].components = map[x.parent].components || []
      map[x.parent].components.push(x)
    } else {
      roots.push(x)
    }
  })
  return roots
}

